void CByteStreamWriter::WriteVarInt32(uint32_t val) {
    while (val >= 0x80) {
        m_Buffer.push_back(static_cast<uint8_t>((val & 0x7F) | 0x80));
        val >>= 7;
    }
    m_Buffer.push_back(static_cast<uint8_t>(val & 0x7F));
}

void CByteStreamWriter::WriteVarInt64(uint64_t val) {
    while (val >= 0x80) {
        m_Buffer.push_back(static_cast<uint8_t>((val & 0x7F) | 0x80));
