            const float range = fieldInfo.highValue - fieldInfo.lowValue;
            a.pitch = fieldInfo.lowValue + (static_cast<float>(stream.ReadUBits(static_cast<size_t>(fieldInfo.bitCount))) / maxVal) * range;
